I was trying to find a way to share my shiny app with my student without (1) requiring them to install git and (2) allowing them to update the app whenever one or more of the files changes. While install_github is great it requires students to be online and it download the entire app every time. If dropbox offered a read-only option I wouldn't need this at all but ...

As the package maintainer I create a file with information on all app files every time I push a change to github. Lines added at the top of server.R:

dbox_remote <- file.info <http://file.info>(list.files(recursive = TRUE, include.dirs = TRUE))
save(dbox_remote, file = "dbox_remote.rda")

update.R is used to check if all files the user has in their local install are up to date. If any are not, or if some files are missing, they are downloaded from github. Shiny's source code provided most of the inspiration. A full install is slow. If your app has larger files (e.g., data) using this form of updating may be worthwhile. Suggestions/comments are welcome.

update.R code

download.file_win <- function(url,f) {
  download.file(paste0(url,f),f, quiet = TRUE)
}

download.file_mac <- function(url,f) {
  download.file(paste0(url,f),f, method = 'curl', quiet = TRUE, extra = '-L')
}

update_app <- function(url) {

  os_type <- .Platform$OS.type

  if (os_type == 'windows') {
    # copied from Shiny source code
    mySI2 <- `::`(utils, 'setInternet2')
    internet2_start <- mySI2(NA)
    on.exit(mySI2(internet2_start))
    mySI2(TRUE)
    download <- download.file_win
  } else {
    download <- download.file_mac
	  # try_remote <- try(download.file(paste0(url,f),f, method = 'curl', quiet = TRUE, extra = '-L'), silent = TRUE)
  }

  f <- 'dbox_remote.rda'
  try_remote <- try(download(url,f), silent = TRUE)

  if(!is(try_remote, 'try-error')) {

    dbox_local <- file.info <http://file.info>(list.files(recursive = TRUE, include.dirs = TRUE))
    load(f)

    if(dim(dbox_remote)[1] == dim(dbox_local)[1]) {
      if(sum(dbox_remote$mtime == dbox_local$mtime) == dim(dbox_local)[1]) stop
    }

    # new dirs
    rn_local_dirs <- rownames(dbox_local[dbox_local$isdir == TRUE, ])
    rn_remote_dirs <- rownames(dbox_remote[dbox_remote$isdir == TRUE, ])
    new_dirs <- rn_remote_dirs[!(rn_remote_dirs %in% rn_local_dirs)]

    for(d in new_dirs) {
      dir.create(d)
    }

    # new files
    rn_local_files <- rownames(dbox_local[dbox_local$isdir == FALSE, ])
    rn_remote_files <- rownames(dbox_remote[dbox_remote$isdir == FALSE, ])
    new_files <- rn_remote_files[!(rn_remote_files %in% rn_local_files)]

    files2get <- new_files

    # existing files
    existing_files <- rn_remote_files[rn_remote_files %in% rn_local_files]
    files2get <- c(files2get, existing_files[dbox_remote[existing_files,]$mtime > dbox_local[existing_files,]$mtime])

    for(f in files2get) {
      cat(paste("Getting file",f,"\n"))
      download(url,f)
    }
  }
}

